fr.exercice_solution:
import androidx.compose.runtime.*
import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import androidx.lifecycle.viewModelScope

// 1. Data class Task
data class Task(
    val id: Long,
    val title: String,
    val isCompleted: Boolean = false
)

// 2. TodoViewModel qui hérite de ViewModel
class TodoViewModel : ViewModel() {
    // 3. StateFlow pour stocker les tâches, initialValue avec quelques tâches
    private val _tasks = MutableStateFlow(
        listOf(
            Task(id = 1, title = "Acheter du pain", isCompleted = true),
            Task(id = 2, title = "Appeler le médecin"),
            Task(id = 3, title = "Faire du sport")
        )
    )
    val tasks: StateFlow<List<Task>> = _tasks.asStateFlow()

    // 4. Fonction pour ajouter une tâche
    fun addTask(title: String) {
        val newTask = Task(
            id = System.currentTimeMillis(),
            title = title
        )
        _tasks.value = _tasks.value + newTask
    }

    // 5. Fonction pour basculer l'état d'une tâche
    fun toggleTask(id: Long) {
        _tasks.value = _tasks.value.map { task ->
            if (task.id == id) task.copy(isCompleted = !task.isCompleted)
            else task
        }
    }

    // 6. Fonction pour supprimer une tâche
    fun deleteTask(id: Long) {
        _tasks.value = _tasks.value.filter { it.id != id }
    }
}

@Composable
fun TodoScreen() {
    // 7. Obtenir le ViewModel
    val viewModel = remember { viewModel<TodoViewModel>() }
    val tasks by viewModel.tasks.collectAsState()

    Column(modifier = Modifier.padding(16.dp)) {
        Text("Ma Todo List (${tasks.count()} tâches)")
        Spacer(modifier = Modifier.height(16.dp))

        LazyColumn {
            items(tasks) { task ->
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(8.dp)
                        .clickable { viewModel.toggleTask(task.id) },
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Text(
                        text = task.title,
                        modifier = Modifier.weight(1f),
                        decorationLine = if (task.isCompleted) TextDecoration.LineThrough else null
                    )
                    IconButton(onClick = { viewModel.deleteTask(task.id) }) {
                        Icon(Icons.Default.Delete, contentDescription = "Supprimer")
                    }
                }
            }
        }
    }
}

